import json,re
d=json.load(open('/tmp/layout.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        if o.get('type')=='table':
            out.append('\n[TABLE]')
            for row in o.get('rows',[]):
                cells=[]
                for c in row:
                    buf=[]; walk(c,buf); cells.append(' '.join(x for x in buf if x.strip()))
                out.append(' | '.join(cells))
            out.append('[/TABLE]\n')
            return
        if o.get('type')=='heading': out.append('\n## '+str(o.get('text',''))+'\n')
        for k,v in o.items():
            if k in ('rows',): continue
            walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
txt=' '.join(out)
txt=re.sub(r' +',' ',txt)
open('/tmp/layout.txt','w').write(txt)
print(len(txt))
"
